// SPDX-License-Identifier: Apache-2.0
//
//! DRA-395 evidence: observe the CURRENT head-of-line behaviour of
//! `Core::pump` (src/scheduler/core.rs). These tests assert what the
//! reference scheduler does today; they are not a specification.

mod common;

use common::{req, H};
use spark_harness::execution::TaskState;
use spark_harness::scheduler::{
    EventKind, Outcome, ProvisionalConfig, ResourceLimits, SchedError,
};

const CPU: u32 = 4;

fn cfg(queue_capacity: usize) -> ProvisionalConfig {
    ProvisionalConfig {
        enabled: true,
        queue_capacity,
        limits: ResourceLimits {
            cpu_slots: CPU,
            memory_bytes: 1 << 40,
            max_concurrency: 4,
        },
        lease_ttl: 1_000,
        dedup_window: 64,
    }
}

fn provisional(h: &H, ids: &[&str]) -> Vec<String> {
    ids.iter()
        .filter(|t| h.sched.state(t).unwrap() == TaskState::Provisional)
        .map(|t| t.to_string())
        .collect()
}

fn free_cpu(h: &H) -> u32 {
    CPU - h.sched.permits_in_use().cpu_in_use
}

fn obs(scenario: &str, step: &str, h: &H, ids: &[&str], extra: &str) {
    let pool = h.sched.permits_in_use();
    let states: Vec<String> = ids
        .iter()
        .map(|t| {
            let i = h.sched.task(t).unwrap();
            format!("{t}:{:?}:queued={}", i.state, i.queued)
        })
        .collect();
    println!(
        "DRA395-RUST {scenario} step={step} running=[{}] free_cpu={} running_count={} queue=[{}] states=[{}]{extra}",
        provisional(h, ids).join(","),
        free_cpu(h),
        pool.running,
        h.sched.queue().join(","),
        states.join(" "),
    );
}

#[test]
fn a_blocked_head() {
    let ids = ["a", "b", "c"];
    let mut h = H::new(cfg(64));
    let fx = h.register("a", 3, &[]);
    assert_eq!(fx.dispatched, vec!["a"]);
    let fx_b = h.register("b", 2, &[]);
    let fx_c = h.register("c", 1, &[]);
    obs(
        "blocked_head",
        "after_register_abc",
        &h,
        &ids,
        &format!(
            " dispatched_by_b={:?} dispatched_by_c={:?}",
            fx_b.dispatched, fx_c.dispatched
        ),
    );
    // Current behaviour: b (2 cpu) heads the queue and does not fit next to
    // a (3 of 4); c (1 cpu) would fit but is behind b and stays queued.
    assert!(fx_b.dispatched.is_empty());
    assert!(fx_c.dispatched.is_empty());
    assert_eq!(h.sched.queue(), vec!["b", "c"]);
    assert_eq!(free_cpu(&h), 1);
    let c = h.sched.task("c").unwrap();
    assert_eq!((c.state, c.queued), (TaskState::Blocked, true));

    // a leaves Provisional (WorkDone -> AwaitingFinalProof) and releases
    // its permits.
    let fx = h.work_done("a");
    obs(
        "blocked_head",
        "after_work_done_a",
        &h,
        &ids,
        &format!(" dispatched_by_release={:?}", fx.dispatched),
    );
    assert_eq!(fx.dispatched, vec!["b", "c"]);
    assert_eq!(free_cpu(&h), 1);
}

#[test]
fn b_bounded_queue_exclusion() {
    let ids = ["a", "b", "d", "e"];
    let mut h = H::new(cfg(2));
    assert_eq!(h.register("a", 3, &[]).dispatched, vec!["a"]);
    h.register("b", 2, &[]);
    h.register("d", 2, &[]);
    let fx_e = h.register("e", 1, &[]);
    obs(
        "queue_exclusion",
        "after_register_abde",
        &h,
        &ids,
        &format!(" dispatched_by_e={:?}", fx_e.dispatched),
    );
    assert!(fx_e.dispatched.is_empty());
    assert_eq!(h.sched.queue(), vec!["b", "d"]);
    assert_eq!(free_cpu(&h), 1);
    let e = h.sched.task("e").unwrap();
    assert_eq!((e.state, e.queued), (TaskState::Blocked, false));

    let fx = h.work_done("a");
    obs(
        "queue_exclusion",
        "after_work_done_a",
        &h,
        &ids,
        &format!(" dispatched_by_release={:?}", fx.dispatched),
    );
    assert_eq!(fx.dispatched, vec!["b", "d"]);
    assert_eq!(free_cpu(&h), 0);
    let e = h.sched.task("e").unwrap();
    assert_eq!((e.state, e.queued), (TaskState::Blocked, true));
}

#[test]
fn c_impossible_request() {
    let mut h = H::new(cfg(64));
    let r = h.send(EventKind::RegisterTask {
        task: "big".into(),
        resources: req(5),
        producers: vec![],
    });
    let registered = h.sched.task("big").is_some();
    println!(
        "DRA395-RUST impossible_request cpu_request=5 cpu_limit={CPU} result={} registered={registered} queue=[{}]",
        match &r {
            Ok(Outcome::Applied(fx)) => format!("Applied(dispatched={:?})", fx.dispatched),
            Ok(o) => format!("{o:?}"),
            Err(e) => format!("Err({e:?})"),
        },
        h.sched.queue().join(","),
    );
    assert!(matches!(&r, Err(SchedError::ExceedsCapacity(t)) if t == "big"), "{r:?}");
    assert!(!registered);
}
